$currentState = "LowLoad"

function UpdateSchedulerState {
    param($currentState, $transitionMatrix)
    $rand = Get-Random
    $cumulative = 0.0
    foreach ($state in $transitionMatrix[$currentState].Keys) {
        $cumulative += $transitionMatrix[$currentState][$state]
        if ($rand -le $cumulative) {
            return $state
